-- Two clients' sets may share a class's table: each client's own rows go in
-- first, in this order, and a spell already there by id or by name (an
-- ally's Barkskin beside your own) is not added twice.
local function Named(key) return key and key:match("^combat%-[%w_]+%-(.+)$") end
for _, catalogue in ipairs({ "camelot", "vanilla", "tbc", "mists", "mainline" }) do
	for class, rows in pairs(GENERATED[catalogue] or {}) do
		local existing = ns.MOMENT_SETS[catalogue][class] or {}
		ns.MOMENT_SETS[catalogue][class] = existing
		local used, named, last = {}, {}, 0
		for _, row in ipairs(existing) do
			last = math.max(last, row.slot or 0)
			for _, id in ipairs(row.ranks or {}) do used[id] = true end
			if Named(row.key) then named[Named(row.key)] = true end
		end
		for _, row in ipairs(rows) do
			local new = not named[Named(row.key)]
			for _, id in ipairs(row.ranks) do if used[id] then new = false break end end
			if new then
				last = last + 1
				row.slot = last
				existing[#existing + 1] = row
				ns.MOMENT_DEFAULTS[row.key] = false
				ns.MOMENT_KEYS[#ns.MOMENT_KEYS + 1] = row.key
				for _, id in ipairs(row.ranks) do used[id] = true end
				named[Named(row.key)] = true
			end
		end
	end
end
